package llm

import (
	"encoding/json"
	"io"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"unicode/utf16"
	"unicode/utf8"
)

// The only oracle is generated by the checked-in original TypeScript classes
// on a disposable GitHub runner. No authored data, host configuration, or keys
// are read, and a missing oracle must fail (not skip) GitHub CI.
func TestOriginalTypeScriptVisibleContract(t *testing.T) {
	contractPath := os.Getenv("GO_VISIBLE_CONTRACT")
	if contractPath == "" {
		if os.Getenv("GITHUB_ACTIONS") == "true" {
			t.Fatal("GO_VISIBLE_CONTRACT is required on GitHub Actions")
		}
		t.Skip("original TypeScript oracle is generated only on GitHub Actions")
	}
	base := os.Getenv("RUNNER_TEMP")
	if os.Getenv("GITHUB_ACTIONS") != "true" || !filepath.IsAbs(base) || !filepath.IsAbs(contractPath) || filepath.Clean(contractPath) != contractPath || filepath.Base(contractPath) != "visible-contract.json" {
		t.Fatal("visible contract must be an explicitly named canonical GitHub runner fixture")
	}
	relative, err := filepath.Rel(base, contractPath)
	if err != nil || relative == "." || strings.HasPrefix(relative, "..") || filepath.IsAbs(relative) {
		t.Fatal("visible contract must be inside RUNNER_TEMP")
	}
	file, err := os.Open(contractPath)
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	type step struct {
		Input     []uint16   `json:"input"`
		Emitted   []uint16   `json:"emitted"`
		Text      []uint16   `json:"text"`
		Reasoning [][]uint16 `json:"reasoning"`
	}
	type contractCase struct {
		Name   string   `json:"name"`
		Steps  []step   `json:"steps"`
		Finish []uint16 `json:"finish"`
		Text   []uint16 `json:"text"`
	}
	var contract struct {
		FormatVersion   int            `json:"formatVersion"`
		Encoding        string         `json:"encoding"`
		SourceHasFinish bool           `json:"sourceHasFinish"`
		Cases           []contractCase `json:"cases"`
	}
	decoder := json.NewDecoder(io.LimitReader(file, 16*1024*1024))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&contract); err != nil {
		t.Fatal(err)
	}
	var extra any
	if err := decoder.Decode(&extra); err != io.EOF {
		t.Fatalf("contract must contain exactly one JSON document: %v", err)
	}
	if contract.FormatVersion != 1 || contract.Encoding != "utf16-code-units" || contract.SourceHasFinish || len(contract.Cases) < 800 {
		t.Fatal("unexpected oracle version, encoding, finish behavior, or insufficient cases")
	}
	seen := make(map[string]bool)
	for _, tc := range contract.Cases {
		if seen[tc.Name] || len(tc.Steps) == 0 || tc.Finish == nil || tc.Text == nil {
			t.Fatalf("invalid or duplicate contract case %q", tc.Name)
		}
		seen[tc.Name] = true
		t.Run(tc.Name, func(t *testing.T) {
			visible := NewVisibleFilter()
			var reasoningChunks []string
			reasoning := NewInBandReasoning(func(chunk string) {
				reasoningChunks = append(reasoningChunks, chunk)
			})
			noCallback := NewInBandReasoning(nil)
			for index, item := range tc.Steps {
				if item.Input == nil || item.Emitted == nil || item.Text == nil || item.Reasoning == nil {
					t.Fatalf("step %d is missing a required code-unit array", index)
				}
				input := contractUTF16String(item.Input)
				if got, want := visible.Push(input), contractUTF16String(item.Emitted); got != want {
					t.Fatalf("step %d emission = %q, want %q", index, got, want)
				}
				if got, want := visible.Text(), contractUTF16String(item.Text); got != want {
					t.Fatalf("step %d text = %q, want %q", index, got, want)
				}
				reasoningChunks = make([]string, 0)
				reasoning.Push(input)
				noCallback.Push(input)
				wantReasoning := make([]string, 0, len(item.Reasoning))
				for _, chunk := range item.Reasoning {
					wantReasoning = append(wantReasoning, contractUTF16String(chunk))
				}
				if !reflect.DeepEqual(reasoningChunks, wantReasoning) {
					t.Fatalf("step %d reasoning = %q, want %q", index, reasoningChunks, wantReasoning)
				}
				// Finish is not a new parse transition: it may neither disclose
				// pending tags nor reset state before a subsequent Push.
				if visible.Finish() != "" || visible.Text() != contractUTF16String(item.Text) {
					t.Fatalf("step %d finish changed original completion behavior", index)
				}
			}
			for repeat := 0; repeat < 2; repeat++ {
				if got, want := visible.Finish(), contractUTF16String(tc.Finish); got != want {
					t.Fatalf("finish = %q, want %q", got, want)
				}
				if got, want := visible.Text(), contractUTF16String(tc.Text); got != want {
					t.Fatalf("finished text = %q, want %q", got, want)
				}
			}
		})
	}
	for _, name := range []string{
		"empty/whole", "plain/units", "nested/units", "unmatched-close/whole",
		"unmatched-open/units", "case/units", "kelvin-case/units", "dotted-i/whole",
		"partial-open/whole", "partial-close/whole", "hidden-partial/units",
		"whitespace/units", "surrogate-pair/units", "lone-surrogates/units",
		"surrogate-near-tag/units", "three-way/0-0", "synthetic/127",
	} {
		if !seen[name] {
			t.Errorf("original TypeScript oracle is missing mandatory case %q", name)
		}
	}
}

// Independent fixture decoder: ordinary strings use standard UTF-16 decoding;
// unpaired surrogates use explicit WTF-8 bytes instead of replacement runes.
func contractUTF16String(units []uint16) string {
	var result strings.Builder
	start := 0
	for i := 0; i < len(units); i++ {
		if units[i] < 0xd800 || units[i] > 0xdfff {
			continue
		}
		if units[i] <= 0xdbff && i+1 < len(units) && units[i+1] >= 0xdc00 && units[i+1] <= 0xdfff {
			i++
			continue
		}
		result.WriteString(string(utf16.Decode(units[start:i])))
		unit := uint32(units[i])
		result.Write([]byte{byte(0xe0 + unit/4096), byte(0x80 + (unit/64)%64), byte(0x80 + unit%64)})
		start = i + 1
	}
	result.WriteString(string(utf16.Decode(units[start:])))
	return result.String()
}

func TestVisibleUTF16Representation(t *testing.T) {
	for _, text := range []string{"", "正文 😀 \x00\r\n\t", "\u212a\u0130\u2028\u2029", "𐀀\ue000"} {
		if got := visibleString(utf16.Encode([]rune(text))); got != text || !utf8.ValidString(got) {
			t.Fatalf("valid scalar encoding changed %q to %q", text, got)
		}
		if got := visibleUnits(text); !reflect.DeepEqual(got, visibleUnits(contractUTF16String(utf16.Encode([]rune(text))))) {
			t.Fatalf("UTF-16 decoding changed %q", text)
		}
	}
	units := []uint16{0xd800, 'x', 0xdfff, 0xd83d, 0xde00}
	if got := visibleUnits(contractUTF16String(units)); !reflect.DeepEqual(got, units) {
		t.Fatalf("surrogate units lost: %x, want %x", got, units)
	}
	if got := visibleString(units); got != "\xed\xa0\x80x\xed\xbf\xbf😀" {
		t.Fatalf("incorrect surrogate representation %q", got)
	}
	var visible VisibleFilter
	if visible.Push("\xed\xa0\xbd") != "\xed\xa0\xbd" || visible.Push("\xed\xb8\x80") != "\xed\xb8\x80" || visible.Text() != "😀" {
		t.Fatal("split surrogate emissions or accumulated text differ from JavaScript")
	}
}

func TestVisibleCompletionNeverDisclosesPending(t *testing.T) {
	filter := NewVisibleFilter()
	if filter.Push(" \tA<thi") != " \tA" || filter.Finish() != "" || filter.Text() != " \tA" {
		t.Fatal("partial opening tag leaked at completion")
	}
	if filter.Push("nk>private</think>\r\nB<") != "\r\nB" || filter.Finish() != "" || filter.Text() != " \tA\r\nB" {
		t.Fatal("completion changed pending state or whitespace")
	}
	if filter.Push("not-a-tag>") != "<not-a-tag>" {
		t.Fatal("Finish discarded the original pending partial tag")
	}
}
